arguments.command:
curl -s -X POST "https://slack.com/api/search.messages?token=<TOKEN>&query=in:C_INC+payment+gateway+outage&count=50" -H "Content-Type: application/json" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d); sys.exit()
for m in d['messages']['matches']:
    print(m['channel'], m['ts'], m['user'], repr(m['text'][:120]))
    for r in m.get('reactions',[]):
        print('   reaction:', r['name'], r['users'])
"

